trait IntQueue { def put(x: Int): Unit }
class BasicQueue extends IntQueue { private var xs = List.empty[Int]; def put(x: Int) = xs = xs :+ x }

trait Doubling extends IntQueue { abstract override def put(x: Int) = super.put(2 * x) }
trait Filtering extends IntQueue { abstract override def put(x: Int) = if (x >= 0) super.put(x) }

val q = new BasicQueue with Filtering with Doubling   // rightmost runs first: double, then filter
q.put(3)
